import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

const AddPetPage = () => {
    const navigate = useNavigate();
    const [petData, setPetData] = useState({
        name: "",
        breed: "",
        age: "",
        type: "",
        description: "",
    });

    const handleChange = (e) => {
        const { name, value } = e.target;
        setPetData({ ...petData, [name]: value });
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        console.log("Pet data submitted:", petData);
        alert("Pet added (simulated, no database yet)!");
        navigate("/shelter"); // revine la dashboard
    };

    return (
        <div style={{ padding: "20px" }}>
            <h2>Add a New Pet 🐶🐱</h2>
            <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", maxWidth: "400px" }}>
                <input type="text" name="name" placeholder="Pet Name" onChange={handleChange} required />
                <input type="text" name="breed" placeholder="Breed" onChange={handleChange} required />
                <input type="text" name="age" placeholder="Age" onChange={handleChange} required />
                <select name="type" onChange={handleChange} required>
                    <option value="">Select Type</option>
                    <option value="dog">Dog</option>
                    <option value="cat">Cat</option>
                    <option value="other">Other</option>
                </select>
                <textarea name="description" placeholder="Description" onChange={handleChange} />
                <button type="submit" style={{ marginTop: "10px", padding: "10px", backgroundColor: "#4CAF50", color: "white", border: "none", borderRadius: "5px" }}>Add Pet</button>
            </form>
        </div>
    );
};

export default AddPetPage;
